import {
  addNonEnumerableProperty,
  captureException,
  type MonitorConfig,
  startNewTrace,
  withMonitor,
} from '@sentry/core';
import { isReadAlikeByNodeCron3 } from '../integrations/node-cron';
import { getCronMonitorConfig } from './common';

export interface NodeCronOptions {
  name: string;
  timezone?: string;
}

export interface NodeCron {
  schedule: (
    cronExpression: string,
    callback: (context?: unknown) => void,
    options: NodeCronOptions | undefined,
  ) => unknown;
}

/**
 * Wraps the `node-cron` library with check-in monitoring.
 *
 * ```ts
 * import * as Sentry from "@sentry/node";
 * import * as cron from "node-cron";
 *
 * const cronWithCheckIn = Sentry.cron.instrumentNodeCron(cron);
 *
 * cronWithCheckIn.schedule(
 *   "* * * * *",
 *   () => {
 *     console.log("running a task every minute");
 *   },
 *   { name: "my-cron-job" },
 * );
 * ```
 *
 * On node-cron 4, steps on `*` in the day-of-month or month field (such as every second day) aren't sent as a
 * schedule, because this wrapper can't tell the node-cron version. `nodeCronIntegration` can.
 *
 * @deprecated Use `nodeCronIntegration` instead.
 */
export function instrumentNodeCron<T>(
  lib: Partial<NodeCron> & T,
  monitorConfig: Pick<MonitorConfig, 'isolateTrace'> = {},
): T {
  return new Proxy(lib, {
    get(target, prop) {
      if (prop === 'schedule' && target.schedule) {
        // When 'get' is called for schedule, return a proxied version of the schedule function
        return new Proxy(target.schedule, {
          apply(target, thisArg, argArray: Parameters<NodeCron['schedule']>) {
            const [expression, callback, options] = argArray;

            const name = options?.name;
            const timezone = options?.timezone;

            if (!name) {
              throw new Error('Missing "name" for scheduled job. A name is required for Sentry check-in monitoring.');
            }

            // The node-cron version is unknown here, so check for node-cron 3 quirks, which include those before 4.6.
            const cronConfig = getCronMonitorConfig(expression, timezone, 'node-cron', isReadAlikeByNodeCron3);
            const upsertMonitorConfig = cronConfig && { ...cronConfig, ...monitorConfig };

            const monitoredCallback = async (...args: Parameters<typeof callback>): Promise<void> => {
              const runWithMonitor = (): Promise<void> =>
                withMonitor(
                  name,
                  async () => {
                    // We have to manually catch here and capture the exception because node-cron swallows errors
                    // https://github.com/node-cron/node-cron/issues/399
                    try {
                      // oxlint-disable-next-line typescript/await-thenable, typescript/return-await -- callback may be async at runtime; awaiting inside the try lets us capture its rejection
                      return await callback(...args);
                    } catch (e) {
                      captureException(e, {
                        mechanism: {
                          handled: false,
                          type: 'auto.function.node-cron.instrumentNodeCron',
                        },
                      });
                      throw e;
                    }
                  },
                  upsertMonitorConfig,
                );
              // `withMonitor` reads `isolateTrace` from the monitor config, which is not sent without a schedule.
              return !upsertMonitorConfig && monitorConfig.isolateTrace
                ? startNewTrace(runWithMonitor)
                : runWithMonitor();
            };

            // Tells `nodeCronIntegration` that this task is already monitored.
            addNonEnumerableProperty(monitoredCallback, Symbol.for('sentry.cron.monitored'), true);

            return target.apply(thisArg, [expression, monitoredCallback, options]);
          },
        });
      } else {
        return target[prop as keyof T];
      }
    },
  });
}
